# Generated by .github/scripts/homebrew-formula.sh in xlsft/companion for
# v0.0.7; edits here are overwritten by the next release.
class Companion < Formula
  desc "Voice and screen assistant with local speech recognition"
  homepage "https://github.com/xlsft/companion"
  version "0.0.7"
  license "FSL-1.1-ALv2"

  depends_on :linux

  on_intel do
    url "https://github.com/xlsft/companion/releases/download/v0.0.7/companion-0.0.7-linux-x86_64.tar.gz"
    sha256 "432c663e4571127c5c382eebf00d44c3680a5f312a5a62caeb310573839fcdf6"
  end
  on_arm do
    url "https://github.com/xlsft/companion/releases/download/v0.0.7/companion-0.0.7-linux-aarch64.tar.gz"
    sha256 "24277e427abad3ef31f21391cdcf49c4aa83d6397053a919f1eac5d0304f29d7"
  end

  def install
    # Must stay side by side: the core starts stt-sidecar from its own
    # directory, and the sidecar loads the sherpa-onnx libraries from its
    # own directory.
    libexec.install "companion", "stt-sidecar", "libsherpa-onnx-c-api.so", "libonnxruntime.so"
    bin.install_symlink libexec/"companion"
    share.install Dir["share/*"]
    # Launchers do not search brew's bin; point the entry at it directly.
    inreplace share/"applications/companion.desktop", /^Exec=companion$/, "Exec=#{opt_bin}/companion"
    prefix.install "LICENSE.md", "NOTICE", "licenses"
  end

  def caveats
    <<~EOS
      Companion uses the system graphics stack, PipeWire or PulseAudio and
      xdg-desktop-portal; see https://github.com/xlsft/companion/blob/main/docs/linux.md
      Run `companion -diagnose` to see what this desktop supports.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/companion -version")
  end
end
